-- Investments: account type 5 + per-account details, and SIP link on recurring items.
CREATE TABLE IF NOT EXISTS accounts."InvestmentDetails" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AccountId" integer NOT NULL REFERENCES accounts."Accounts"("Id") ON DELETE CASCADE,
    "Kind" integer NOT NULL DEFAULT 0,
    "CurrentValue" numeric(18,2) NULL,
    "ValuedOn" timestamp with time zone NULL,
    "Symbol" text NULL,
    "Notes" text NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT now(),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT now(),
    "IsDeleted" boolean NOT NULL DEFAULT false,
    "DeletedAt" timestamp with time zone NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_InvestmentDetails_AccountId" ON accounts."InvestmentDetails" ("AccountId");

ALTER TABLE transactions."RecurringTransactions" ADD COLUMN IF NOT EXISTS "LinkedInvestmentAccountId" integer NULL;
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_RecurringTransactions_Accounts_LinkedInvestmentAccountId') THEN
        ALTER TABLE transactions."RecurringTransactions"
            ADD CONSTRAINT "FK_RecurringTransactions_Accounts_LinkedInvestmentAccountId"
            FOREIGN KEY ("LinkedInvestmentAccountId") REFERENCES accounts."Accounts"("Id") ON DELETE SET NULL;
    END IF;
END $$;
